    h = len(grid)
    output = [[c for c in row] for row in grid]  # shallow copy of rows, deep copy of whole

    sequence = [2, 3, 5, 1, 6, 4]
    seq_len = 6

    source_start_col = None
    for r in range(min(h, 20)):
        row_vals = grid[r]
