                    source_start_col = i
                    break
            if source_start_col is not None:
                break

    if source_start_col is None:
        return grid

    for r in range(h):
        row = output[r]
        target_vals_list = []
        for c in range(w):
            val = row[c]
            if val in sequence:
                target_vals_list.append((c, val))

        if not target_vals_list:
