        if first_val in sequence:
            pos_in_seq = sequence.index(first_val)
            start_col = first_c - pos_in_seq

            for i, s in enumerate(sequence):
                col_to_write = start_col + i
                if 0 <= col_to_write < w:
                    output[r][col_to_write] = s

    return output

